CREATE OR REPLACE FUNCTION private.valid_execution_findings(value jsonb, p_version integer)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE name text; finding jsonb; source jsonb; binding jsonb; names text[]:=ARRAY[]::text[]; ids uuid[]:=ARRAY[]::uuid[];
BEGIN
 IF value IS NULL OR p_version IS NULL OR p_version<1 OR jsonb_typeof(value)<>'object'
  OR NOT(value ?& ARRAY['seller_signatures','buyer_signatures','signing_authority','complete_agreement','terms'])
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(value) k WHERE k NOT IN ('seller_signatures','buyer_signatures','signing_authority','complete_agreement','terms','deadline_reviews')) THEN RETURN false; END IF;
 FOREACH name IN ARRAY ARRAY['seller_signatures','buyer_signatures','signing_authority','complete_agreement'] LOOP
  finding:=value->name;
  IF jsonb_typeof(finding) IS DISTINCT FROM 'object'
   OR NOT(finding ?& ARRAY['finding','locator','note'])
   OR (SELECT count(*) FROM jsonb_object_keys(finding))<>3
   OR finding->>'finding' IS DISTINCT FROM 'confirmed'
   OR jsonb_typeof(finding->'locator') IS DISTINCT FROM 'string'
   OR length(trim(finding->>'locator')) NOT BETWEEN 1 AND 1000
   OR finding->>'locator' ~ '[[:cntrl:]]'
   OR jsonb_typeof(finding->'note') IS DISTINCT FROM 'string'
   OR length(trim(finding->>'note')) NOT BETWEEN 20 AND 4000 THEN RETURN false; END IF;
 END LOOP;
 IF NOT private.valid_contract_terms(value->'terms') THEN RETURN false; END IF;
 FOR source IN SELECT * FROM jsonb_array_elements(value->'terms'->'sources') LOOP
  IF (source->>'artifact_version')::integer>p_version THEN RETURN false; END IF;
 END LOOP;
 IF value ? 'deadline_reviews' THEN
  IF jsonb_typeof(value->'deadline_reviews') IS DISTINCT FROM 'array'
   OR jsonb_array_length(value->'deadline_reviews') NOT BETWEEN 1 AND 3 THEN RETURN false; END IF;
  FOR binding IN SELECT * FROM jsonb_array_elements(value->'deadline_reviews') LOOP
   IF jsonb_typeof(binding) IS DISTINCT FROM 'object' OR NOT(binding ?& ARRAY['term','review_id'])
    OR (SELECT count(*) FROM jsonb_object_keys(binding))<>2
    OR binding->>'term' IS NULL OR binding->>'term' NOT IN ('effective','inspection_deadline','closing_deadline')
    OR jsonb_typeof(binding->'review_id') IS DISTINCT FROM 'string'
    OR binding->>'review_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    OR binding->>'term'=ANY(names) OR (binding->>'review_id')::uuid=ANY(ids)
    OR value->'terms'->(binding->>'term')->>'precision' IS DISTINCT FROM 'date' THEN RETURN false; END IF;
   names:=array_append(names,binding->>'term'); ids:=array_append(ids,(binding->>'review_id')::uuid);
  END LOOP;
  FOREACH name IN ARRAY ARRAY['effective','inspection_deadline','closing_deadline'] LOOP
   IF value->'terms'->name->>'precision'='date' AND NOT(name=ANY(names)) THEN RETURN false; END IF;
  END LOOP;
 END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.record_sendgrid_events(p_events jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE e jsonb; v_email text; v_id text; v_msg uuid; v_new text; v_stop boolean;
BEGIN
 IF jsonb_typeof(p_events)<>'array' OR jsonb_array_length(p_events)>1000 THEN RAISE EXCEPTION 'Invalid batch'; END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(p_events) LOOP
  v_email:=lower(trim(e->>'email')); v_id:=e->>'event_id'; v_msg:=NULL;
  IF coalesce(v_email,'')='' OR coalesce(v_id,'')='' THEN RAISE EXCEPTION 'Invalid event'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_email,0));
  IF e->>'message_id' IS NOT NULL THEN
   SELECT id INTO v_msg FROM public.email_messages WHERE id=(e->>'message_id')::uuid AND recipient=v_email AND provider='sendgrid';
  END IF;
  INSERT INTO public.email_delivery_events(event_id,message_id,recipient,event,occurred_at,payload)
  VALUES(v_id,v_msg,v_email,e->>'event',to_timestamp((e->>'timestamp')::double precision),e)
  ON CONFLICT(event_id) DO NOTHING RETURNING event_id INTO v_new;
  IF v_new IS NULL THEN CONTINUE; END IF;
  v_stop:=e->>'event' IN ('unsubscribe','group_unsubscribe','spamreport','bounce');
  IF v_stop THEN
   INSERT INTO public.email_suppressions(email,reason) VALUES(v_email,e->>'event') ON CONFLICT(email) DO NOTHING;
   UPDATE public.leads SET email_sequence_active=false WHERE lower(trim(owner_email))=v_email;
   UPDATE public.buyers SET email_opt_in=false WHERE lower(trim(email))=v_email;
  END IF;
  -- Never remove suppression on group_resubscribe or on out-of-order delivery events.
  IF v_stop OR (v_msg IS NOT NULL AND e->>'event' IN ('delivered','dropped','deferred')) THEN
   INSERT INTO public.app_notifications(recipient_role,type,title,body,action_url,metadata)
   VALUES('admin','pipeline_step','Email ' || (e->>'event'),
    v_email || ': ' || left(coalesce(e->>'reason',e->>'event'),300),'/settings',
    jsonb_build_object('provider','sendgrid','message_id',v_msg,'event_id',v_id,'suppressed',v_stop));
  END IF;
 END LOOP;
 RETURN jsonb_build_object('saved',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_pipeline_deal(p_id uuid, p_operator uuid, p_expected timestamp with time zone, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE saved public.deals%ROWTYPE; proposed public.deals%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND status='approved') THEN RAISE EXCEPTION 'Operator not approved'; END IF;
 IF p_patch ?| ARRAY['id','lead_id','created_by','created_at','updated_at','creation_manifest'] THEN RETURN jsonb_build_object('conflict',true); END IF;
 SELECT * INTO saved FROM public.deals WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('missing',true); END IF;
 IF to_jsonb(saved) @> p_patch THEN RETURN jsonb_build_object('deal',to_jsonb(saved),'reused',true); END IF;
 IF saved.updated_at IS DISTINCT FROM p_expected THEN RETURN jsonb_build_object('conflict',true); END IF;
 proposed:=jsonb_populate_record(saved,p_patch);
 IF proposed.stage NOT IN ('closed','cancelled') AND EXISTS(SELECT 1 FROM public.deals WHERE lead_id=proposed.lead_id AND id<>p_id AND stage NOT IN ('closed','cancelled')) THEN
  RETURN jsonb_build_object('existing_id',(SELECT id FROM public.deals WHERE lead_id=proposed.lead_id AND id<>p_id AND stage NOT IN ('closed','cancelled') LIMIT 1)); END IF;
 IF NOT public.deal_handoff_valid(proposed) THEN RETURN jsonb_build_object('invalid',true); END IF;
 UPDATE public.deals SET
 deal_name=proposed.deal_name,stage=proposed.stage,contract_price=proposed.contract_price,arv=proposed.arv,repair_estimate=proposed.repair_estimate,
 assignment_fee=proposed.assignment_fee,buyer_price=proposed.buyer_price,earnest_money=proposed.earnest_money,
 contract_date=proposed.contract_date,inspection_deadline=proposed.inspection_deadline,closing_date=proposed.closing_date,actual_close_date=proposed.actual_close_date,
 seller_name=proposed.seller_name,buyer_id=proposed.buyer_id,title_company=proposed.title_company,title_contact=proposed.title_contact,title_phone=proposed.title_phone,
 psa_doc_url=proposed.psa_doc_url,assignment_doc_url=proposed.assignment_doc_url,notes=proposed.notes,assigned_to=proposed.assigned_to
 WHERE id=p_id RETURNING * INTO saved;
 PERFORM public.sync_deal_handoff_tasks(saved);
 RETURN jsonb_build_object('deal',to_jsonb(saved),'reused',false);
END $function$
